// The S3 bucket is configured separately in the AWS S3 node.
// folderKey must be a prefix within the bucket.
const policyFolders = ['returns', 'refunds', 'shipping', 'warranty'];
return policyFolders.map(folder => ({
  json: { folderName: folder, folderKey: `policies/${folder}/` }
}));

const items = $input.all();
const CHUNK_SIZE = 1200;       // characters; tune with retrieval evaluation
const CHUNK_OVERLAP = 200;     // characters; tune with retrieval evaluation
const output = [];

for (const item of items) {
  const data = item.json ?? {};
  const fullText = String(data.text || '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  if (!fullText) continue;

  const s3Key = data.Key || data.key || '';
  const fileName = data.fileName || data.FileName || s3Key.split('/').pop() || 'unknown-document.pdf';
  const title = data.info?.Title || fileName.replace(/\.pdf$/i, '').replace(/_/g, ' ');
  const categoryMatch = s3Key.match(/policies\/([^/]+)\//i);
  const category = categoryMatch ? categoryMatch[1].toLowerCase() : 'general';
  const policyMatch = fullText.match(/Policy ID\s*:?\s*([A-Z0-9-]+)/i);
  const documentId = policyMatch ? policyMatch[1].toUpperCase() : fileName.replace(/\.pdf$/i, '').replace(/[^a-zA-Z0-9-]/g, '_');
  const versionMatch = fullText.match(/Version\s*[: ]\s*([0-9.]+)/i);
  const effectiveDateMatch = fullText.match(/Effective date\s*[: ]\s*(\d{4}-\d{2}-\d{2})/i);

  const chunks = [];
  let start = 0;
  while (start < fullText.length) {
    let end = Math.min(start + CHUNK_SIZE, fullText.length);
    if (end < fullText.length) {
      const minEnd = start + Math.floor(CHUNK_SIZE * 0.6);
      const window = fullText.slice(minEnd, end);
      const boundaries = [
        window.lastIndexOf('\n\n'),
        window.lastIndexOf('\n'),
        window.lastIndexOf('. '),
        window.lastIndexOf('? '),
        window.lastIndexOf('! '),
        window.lastIndexOf(' ')
      ];
      const boundary = Math.max(...boundaries);
      if (boundary >= 0) end = minEnd + boundary + 1;
    }

    const chunkText = fullText.slice(start, end).trim();
    if (chunkText) chunks.push(chunkText);
    if (end >= fullText.length) break;

    let nextStart = Math.max(end - CHUNK_OVERLAP, start + 1);
    while (nextStart < end && !/\s/.test(fullText[nextStart])) nextStart++;
    start = nextStart;
  }

  chunks.forEach((chunkText, index) => output.push({
    json: {
      _id: `${documentId}-CHUNK-${String(index + 1).padStart(4, '0')}`,
      document_id: documentId,
      chunk_index: index + 1,
      total_chunks: chunks.length,
      chunk_text: chunkText,
      title,
      category,
      source: s3Key,
      s3_key: s3Key,
      file_name: fileName,
      version: versionMatch ? versionMatch[1] : 'unknown',
      effective_date: effectiveDateMatch ? effectiveDateMatch[1] : 'unknown',
      document_type: 'customer_support_knowledge',
      chunking_method: 'recursive_character_boundary',
      chunk_size_chars: CHUNK_SIZE,
      chunk_overlap_chars: CHUNK_OVERLAP,
      status: 'active'
    }
  }));
}
return output;

const items = $input.all();

const documents = items.map(({ json }) => ({
  _id: json._id,
  chunk_text: json.chunk_text,
  title: json.title,
  category: json.category,
  document_id: json.document_id,
  chunk_index: json.chunk_index,
  total_chunks: json.total_chunks,
  source: json.source,
  s3_key: json.s3_key,
  file_name: json.file_name,
  version: json.version,
  effective_date: json.effective_date,
  document_type: json.document_type,
  status: json.status,
  chunking_method: json.chunking_method,
  chunk_size_chars: json.chunk_size_chars,
  chunk_overlap_chars: json.chunk_overlap_chars
}));

// Prevent accidental duplicate IDs in the batch
const uniqueDocuments = [
  ...new Map(documents.map(doc => [doc._id, doc])).values()
];

return [
  {
    json: {
      documents: uniqueDocuments,
      document_count: uniqueDocuments.length
    }
  }
];
